import { useEffect, useMemo, useState } from "react";
import { Link, NavLink, useLocation, useNavigate } from "react-router-dom";
import { api, type ApiSummary, type ReferenceSite, type RunSummary } from "./api.js";
import { MapView } from "./MapView.js";
import { ExploreWorkspace } from "./Workspace.js";
import { dashboardCandidateRecords, dashboardComparisonForDiscovery, dashboardTargetAvailability, type DashboardCandidate } from "./dashboard-v2-model.js";
import { supportedDiscoveryFactorIds, unsupportedRequiredFactors } from "../../src/discovery/supported-factors.js";
import "./dashboard-v2.css";

type Profile = { missions: { id: string; name: string; objective: string; requiredFactorIds: string[]; optionalFactorIds: string[]; currentEvidenceState: string }[]; dimensions: { factors: { id: string; name: string; definition?: string; unit?: string; evidenceAvailability?: { provider?: string | null; dataset?: string | null } }[] }[] };
type StudyArea = { configurationStatus: string; demonstrationRationale?: string; scientificLimitations: string[]; providerRequestLimit?: number; studyArea: { id: string; label: string; boundingBox: { minLatitude: number; minLongitude: number; maxLatitude: number; maxLongitude: number }; spacingDegrees: number; maxCandidates: number; referenceExclusionKm: number } };
type RunOutcome = { code: string; eligibleCandidateCount: number; reviewableCandidateCount: number; insufficientCandidateCount: number; excludedCandidateCount: number; requiredSourceFailureCount: number; sourceFailureCount: number; explanation: string };
type DiscoveryRun = { runId: string; createdAt: string; missionName?: string; missionId?: string; studyArea?: { label?: string }; candidates: DashboardCandidate[]; comparisonRunId?: string; status?: string; outcome?: RunOutcome };
type HistoryRun = RunSummary & { missionName?: string | null; targetBody?: string | null; studyAreaId?: string | null; earthCandidateCount?: number; evaluatedCellCount?: number; excludedCandidateCount?: number; outcome?: RunOutcome; comparisonRunId?: string | null; searchScope?: { kind: string; bounds: { minLatitude: number; minLongitude: number; maxLatitude: number; maxLongitude: number }; spacingDegrees: number | null; configuredCellLimit: number | null } | null };
type CandidateEvidence = { candidate: DashboardCandidate & { missionId?: string; latitude: number; longitude: number; screening: any; evidence: any[]; limitations: string[]; sources: Record<string, any> }; sources: Record<string, any> };
type Comparison = { runId: string; referenceDataset: { count: number; sites: { id: string; regionName: string | null }[] }; comparisons: { candidateId: string; referenceSiteId: string; factors: { factorId: string; status: string; unit?: string | null; explanation: string; candidate?: any; reference?: any; result?: any; limitations?: string[] }[] }[] };
type MarsTemperatureContext = { status: "ambiguous"; unit: string; method: string; limitations: string[]; candidate: { source: string; measurementType: string; period: { start?: string; end?: string } | null; statistics: { count: number; mean: number; min: number; q25: number; median: number; q75: number; max: number } }; target: { source: string; measurementType: string; solRange: { first: number; last: number }; solCount: number; acceptedRawSampleCount: number; rejectedRawSampleCount: number; statisticsAcrossSelectedSolMeans: { count: number; mean: number; min: number; q25: number; median: number; q75: number; max: number } } };

const nav = [
  ["/dashboard", "Dashboard", "01"], ["/dashboard/explore", "Explore", "02"], ["/dashboard/discover", "Discover", "03"],
  ["/dashboard/results", "Results", "04"], ["/dashboard/compare", "Comparisons", "05"], ["/dashboard/history", "Research History", "06"],
  ["/dashboard/sources", "Data & Sources", "07"], ["/dashboard/methodology", "Methodology", "08"],
] as const;
const factorDescriptions: Record<string, string> = {
  air_temperature_daily_mean: "Daily mean air temperature; gridded NASA POWER estimates for Earth candidates.",
  air_temperature_extremes: "Daily high and low air-temperature estimates.",
  daily_temperature_range: "Difference between daily maximum and minimum air temperature.",
  relative_humidity: "Gridded relative-humidity estimates; not a surface moisture measurement.",
  precipitation: "Gridded precipitation estimates with source missingness retained.",
  wind_speed: "Wind-speed estimate at the provider's stated measurement height.",
  solar_radiation: "Surface shortwave radiation; it is not ultraviolet radiation.",
  elevation_point: "A Copernicus GLO-30 digital surface model pixel, not a terrain suitability measure.",
  mapped_lithology: "Generalized GLiM mapped class, not site-scale field truth or mineral detection.",
};

function useRemote<T>(path: string | null, initial: T) {
  const [state, setState] = useState<{ data: T; loading: boolean; error: string }>({ data: initial, loading: true, error: "" });
  useEffect(() => { let active = true; if (!path) { setState({ data: initial, loading: false, error: "" }); return () => { active = false; }; } setState({ data: initial, loading: true, error: "" }); void api<T>(path).then((data) => { if (active) setState({ data, loading: false, error: "" }); }).catch((error: Error) => { if (active) setState({ data: initial, loading: false, error: error.message || "Data could not be loaded." }); }); return () => { active = false; }; }, [path]);
  return state;
}
function Panel({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <section className={`dashboard-v2-panel ${className}`}>{children}</section>; }
function Header({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <header className="dashboard-v2-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action}</header>; }
function Notice({ children, tone = "warn" }: { children: React.ReactNode; tone?: "warn" | "error" | "info" }) { return <div className={`dashboard-v2-notice notice-${tone}`} role={tone === "error" ? "alert" : "status"}>{children}</div>; }
function CandidateMap({ candidates, references = [], loading = false, onCandidate }: { candidates: DashboardCandidate[]; references?: ReferenceSite[]; loading?: boolean; onCandidate?: (id: string) => void }) {
  const records = useMemo(() => [
    ...references.filter((item) => Number.isFinite(item.latitude) && Number.isFinite(item.longitude)).map((item) => ({ id: item.id, name: item.regionName ?? item.id, kind: "known_analog" as const, latitude: item.latitude!, longitude: item.longitude!, approximate: item.coordinatesApproximate, detail: item.country ?? undefined })),
    ...dashboardCandidateRecords(candidates, "Latest bounded Earth discovery"),
  ], [candidates, references]);
  const selected = onCandidate ? (record: { id: string; kind: string }) => { if (record.kind === "candidate_region") onCandidate(record.id); } : undefined;
  return <MapView records={records} loading={loading} onSelect={selected ? (record) => selected(record) : undefined} />;
}
function CandidateRows({ candidates, runId, supportedOnly = true, emptyMessage }: { candidates: DashboardCandidate[]; runId?: string; supportedOnly?: boolean; emptyMessage?: string }) {
  const rows = candidates.filter((item) => item.recordType === "candidate_region" && (!supportedOnly || item.status === "evidence_supported_for_review"));
  if (!rows.length) return <div className="dashboard-v2-empty">{emptyMessage ?? "No candidate locations are stored in this run."}</div>;
  return <div className="dashboard-v2-candidate-list">{rows.map((item) => <article key={item.id}><div><b>{item.id}</b><span>{item.latitude.toFixed(4)}°, {item.longitude.toFixed(4)}° · approximate grid-cell center</span><small>{item.status?.replaceAll("_", " ") ?? "Screening state not recorded"}</small>{item.screening?.reasons?.map((reason, index) => <small key={`${item.id}-reason-${index}`}>{reason}</small>)}</div><Link className="text-link" to={`/dashboard/candidate/${encodeURIComponent(item.id)}${runId ? `?run=${encodeURIComponent(runId)}` : ""}`}>Inspect evidence →</Link></article>)}</div>;
}

export default function DashboardV2() {
  const location = useLocation();
  const navigate = useNavigate();
  const base = "/dashboard";
  const tail = location.pathname.slice(base.length).replace(/^\//, "");
  const segments = tail.split("/").filter(Boolean);
  let content: React.ReactNode;
  if (!segments.length) content = <HomeV2 />;
  else if (segments[0] === "explore" && segments.length === 1) content = <ExploreWorkspace dashboardV2 />;
  else if (segments[0] === "discover") content = <DiscoverV2 />;
  else if (segments[0] === "results" && segments[1]) content = <Results runId={segments[1]} />;
  else if (segments[0] === "results") content = <LatestResults />;
  else if ((segments[0] === "history" || segments[0] === "runs") && segments[1]) content = <Results runId={segments[1]} />;
  else if (segments[0] === "history" || segments[0] === "runs") content = <RunsV2 />;
  else if (segments[0] === "candidate" && segments[1]) content = <CandidateV2 candidateId={decodeURIComponent(segments[1])} />;
  else if (segments[0] === "compare") content = <CompareV2 />;
  else if (segments[0] === "sources") content = <DataSourcesV2 />;
  else if (segments[0] === "methodology") content = <MethodologyV2 />;
  else content = <DashboardNotFound />;
  return <div className="dashboard-v2-layout" data-testid="dashboard-v2">
    <aside className="dashboard-v2-sidebar" aria-label="Dashboard navigation">
      <div className="dashboard-v2-sidebar-head"><span className="eyebrow">RESEARCH WORKSPACE</span><b>Dashboard</b></div>
      <nav>{nav.map(([href, label, number]) => <NavLink end={href === base} key={href} to={href}><span>{number}</span>{label}</NavLink>)}</nav>
      <div className="dashboard-v2-sidebar-bottom"><span>Target bodies</span><b>Mars · bounded workflow</b><small>Moon discovery is not yet supported by validated target data.</small><Link to="/moon">Open Moon catalog →</Link><Link to="/dashboard-legacy">Open previous workspace</Link></div>
    </aside>
    <div className="dashboard-v2-content">{content}</div>
  </div>;
}

function HomeV2() {
  const navigate = useNavigate();
  const summary = useRemote<ApiSummary | null>("/summary", null);
  const discovery = useRemote<{ runs: HistoryRun[] }>("/discovery-runs", { runs: [] });
  const comparisons = useRemote<{ runs: RunSummary[] }>("/comparison-runs", { runs: [] });
  const references = useRemote<{ records: ReferenceSite[] }>("/references", { records: [] });
  const candidates: DashboardCandidate[] = summary.data?.latestDiscovery?.candidates ?? [];
  const reviewableCandidateCount = dashboardCandidateRecords(candidates, "").length;
  const recent = [...discovery.data.runs.map((run) => ({ ...run, kind: "Discovery" })), ...comparisons.data.runs.map((run) => ({ ...run, kind: "Comparison" }))].sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt))).slice(0, 5);
  return <div className="dashboard-v2-page">
    <Header eyebrow="TERRAMATCH · RESEARCH OVERVIEW" title="Earth candidates, with evidence attached." description="Start a bounded Mars-analog search, inspect real Earth candidate evidence, and review what the current data can support." action={<Link className="primary-button" to="/dashboard/discover">Start new discovery ↗</Link>} />
    {(summary.error || discovery.error || comparisons.error) && <Notice tone="error">Workspace data could not be fully loaded: {summary.error || discovery.error || comparisons.error}</Notice>}
    <div className="dashboard-v2-metrics" aria-label="Current data summary">
      {summary.data && <><div><b>{summary.data.referenceCount}</b><span>Earth reference records</span></div><div><b>{reviewableCandidateCount}</b><span>Latest-run candidates with required evidence</span></div><div><b>{summary.data.comparisonPairCount}</b><span>Archived candidate/reference pairs</span></div></>}
    </div>
    <div className="dashboard-v2-home-grid">
      <Panel className="dashboard-v2-home-map"><div className="dashboard-v2-panel-head"><div><span className="eyebrow">EARTH · ACTUAL STORED LOCATIONS</span><h2>Candidate and reference context</h2></div><Link to="/dashboard/explore" className="text-link">Open map →</Link></div><CandidateMap candidates={candidates} references={references.data.records} loading={summary.loading || references.loading} onCandidate={(id) => navigate(`/dashboard/candidate/${encodeURIComponent(id)}`)} /></Panel>
      <Panel><div className="dashboard-v2-panel-head"><div><span className="eyebrow">RECENT RESEARCH</span><h2>Saved runs</h2></div><Link to="/dashboard/history" className="text-link">Research history →</Link></div>{discovery.loading || comparisons.loading ? <p role="status">Loading saved runs…</p> : recent.length ? <div className="dashboard-v2-run-list">{recent.map((run) => <Link key={`${run.kind}-${run.runId}`} to={run.kind === "Discovery" ? `/dashboard/history/${encodeURIComponent(run.runId)}` : `/dashboard/compare?run=${encodeURIComponent(run.runId)}`}><span>{run.kind}</span><b>{run.studyArea ?? run.missionId ?? "Saved research"}</b><small>{run.createdAt} · {run.candidateCount ?? 0} candidate(s)</small></Link>)}</div> : <div className="dashboard-v2-empty">No saved runs yet. Start the bounded Mars discovery to create a real result.</div>}</Panel>
      <Panel><div className="dashboard-v2-panel-head"><div><span className="eyebrow">SUPPORTED TODAY</span><h2>Data coverage</h2></div></div><ul className="dashboard-v2-coverage"><li><b>Mars</b><span>One allowlisted Atacama bounded demonstration workflow</span></li><li><b>Earth</b><span>{references.data.records.length || "—"} archived references; provider-backed candidate sampling is limited to configured cells</span></li><li><b>Moon</b><span>One LOLA product acquired and processed; shown in Explore as an unvalidated relative-height research display. No validated scientific layers.</span></li></ul></Panel>
      <Panel><div className="dashboard-v2-panel-head"><div><span className="eyebrow">NEXT STEP</span><h2>Configure a supported search</h2></div></div><p className="dashboard-v2-copy">The current discovery is bounded to an allowlisted Earth study area. Its output screens evidence availability; it does not rank analogs or assess mission suitability.</p><Link className="secondary-button" to="/dashboard/discover">Review supported criteria →</Link></Panel>
    </div>
  </div>;
}

function DiscoverV2() {
  const profile = useRemote<Profile | null>("/profile", null);
  const areas = useRemote<{ studyAreas: StudyArea[] }>("/study-areas", { studyAreas: [] });
  const [body, setBody] = useState<"mars" | "moon">("mars");
  const [missionId, setMissionId] = useState("extreme_environment_operations");
  const [areaId, setAreaId] = useState("atacama-climate-transect-v2");
  const [job, setJob] = useState<any>(null);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const navigate = useNavigate();
  useEffect(() => { if (!areas.data.studyAreas.length || areas.data.studyAreas.some((item) => item.studyArea.id === areaId)) return; setAreaId(areas.data.studyAreas[0].studyArea.id); }, [areas.data.studyAreas, areaId]);
  useEffect(() => { if (!job?.jobId || ["completed", "failed"].includes(job.status)) return; let active = true; const timer = window.setInterval(() => { void api<any>(`/jobs/${encodeURIComponent(job.jobId)}`).then((next) => { if (active) setJob(next); }).catch((reason: Error) => { if (active) setError(reason.message); }); }, 1500); return () => { active = false; window.clearInterval(timer); }; }, [job?.jobId, job?.status]);
  const mission = profile.data?.missions.find((item) => item.id === missionId);
  const area = areas.data.studyAreas.find((item) => item.studyArea.id === areaId);
  const factorMap = new Map((profile.data?.dimensions ?? []).flatMap((dimension) => dimension.factors.map((item) => [item.id, item] as const)));
  const supported = supportedDiscoveryFactorIds;
  const unsupportedMissionFactors = mission ? unsupportedRequiredFactors(mission.requiredFactorIds) : [];
  const target = dashboardTargetAvailability(body);
  const start = async () => { setError(""); if (unsupportedMissionFactors.length) { setError(`This profile cannot run yet because required evidence is not supported: ${unsupportedMissionFactors.join(", ")}.`); return; } setSubmitting(true); try { const result = await api<any>("/jobs", { method: "POST", headers: { "Idempotency-Key": `dashboard-v2-${crypto.randomUUID()}` }, body: JSON.stringify({ missionId, studyAreaId: areaId }) }); setJob(result); } catch (reason) { setError((reason as Error).message || "Discovery could not be started."); } finally { setSubmitting(false); } };
  return <div className="dashboard-v2-page"><Header eyebrow="DISCOVER · M07" title="Set up a defensible search." description="Choose a supported target profile and one configured Earth study area. This is a bounded evidence-screening workflow—not a global search or analog ranking." />
    {(profile.error || areas.error) && <Notice tone="error">Discovery configuration could not be loaded: {profile.error || areas.error}</Notice>}
    <div className="dashboard-v2-discovery-grid"><Panel><div className="dashboard-v2-form-grid"><label>Target body<select value={body} onChange={(event) => setBody(event.target.value as "mars" | "moon")}><option value="mars">Mars</option><option value="moon">Moon</option></select></label><label>Earth search area<select disabled={body === "moon" || !areas.data.studyAreas.length} value={areaId} onChange={(event) => setAreaId(event.target.value)}>{areas.data.studyAreas.map((item) => <option key={item.studyArea.id} value={item.studyArea.id}>{item.studyArea.label}</option>)}</select></label><label>Mission profile<select disabled={body === "moon" || !profile.data?.missions.length} value={missionId} onChange={(event) => setMissionId(event.target.value)}>{profile.data?.missions.map((item) => { const blocked = unsupportedRequiredFactors(item.requiredFactorIds).length > 0; return <option key={item.id} value={item.id} disabled={blocked}>{item.name}{blocked ? " · required evidence unavailable" : ""}</option>; })}</select></label><div className="dashboard-v2-search-scope"><span className="eyebrow">EARTH SEARCH SCOPE</span><b>{area?.studyArea.label ?? "No supported area available"}</b><small>Allowlisted regional bounds only. Global and custom scopes are not configured.</small></div></div>
      {body === "moon" && <Notice>{target.message} The LOLA previews are unvalidated, so they cannot be used to run a lunar discovery.</Notice>}
      {body === "mars" && mission && <><div className="dashboard-v2-profile"><b>{mission.name}</b><p>{mission.objective}</p><small>Mars observational context: Curiosity REMS ambient air temperature at Gale Crater. Profile evidence state: {mission.currentEvidenceState.replaceAll("_", " ")}</small></div><div className="dashboard-v2-criteria"><span className="eyebrow">REQUIRED EVIDENCE · IN PLAIN LANGUAGE</span>{mission.requiredFactorIds.map((id) => { const factor = factorMap.get(id); const ready = supported.has(id); return <article key={id}><span className={`state ${ready ? "state-available" : "state-unavailable"}`}><i />{ready ? "Request supported" : "Not in current pipeline"}</span><div><b>{factor?.name ?? id.replaceAll("_", " ")}</b><p>{factorDescriptions[id] ?? factor?.definition ?? "This profile requirement remains explicit; the current provider pipeline may not supply it."}</p><small>{factor?.evidenceAvailability?.provider ?? "Provider not configured"}{factor?.evidenceAvailability?.dataset ? ` · ${factor.evidenceAvailability.dataset}` : ""}</small></div></article>; })}</div>
      {area && <div className="dashboard-v2-area"><b>Configured geographic bounds</b><span>{area.studyArea.boundingBox.minLatitude}–{area.studyArea.boundingBox.maxLatitude}° latitude · {area.studyArea.boundingBox.minLongitude}–{area.studyArea.boundingBox.maxLongitude}° longitude</span><small>{area.studyArea.spacingDegrees}° grid · at most {area.studyArea.maxCandidates} candidate cells · {area.studyArea.referenceExclusionKm} km point-reference exclusion</small><p>{area.demonstrationRationale} {area.scientificLimitations.join(" ")}</p></div>}</>}
      {error && <Notice tone="error">{error}</Notice>}
      <button className="primary-button" type="button" disabled={body !== "mars" || !mission || unsupportedMissionFactors.length > 0 || !area || submitting || (!!job && !["completed", "failed"].includes(job.status))} onClick={() => void start()}>{submitting ? "Submitting…" : job && !["completed", "failed"].includes(job.status) ? "Discovery in progress…" : "Start bounded Mars discovery ↗"}</button>
      <p className="dashboard-v2-fineprint">Starting discovery creates a real job and may make provider requests. No job runs until this button is pressed. Results report evidence availability and are not scientific suitability judgments.</p>
      </Panel><Panel className="dashboard-v2-job-panel"><span className="eyebrow">LIVE JOB STATUS</span><h2>{job ? job.status.replaceAll("_", " ") : "Ready when you are"}</h2>{job ? <><small>Job created {job.createdAt}</small>{job.stages?.map((stage: any) => <div className="dashboard-v2-stage" key={stage.id}><span className={`state state-${String(stage.status).replaceAll("_", "-")}`}><i />{stage.status.replaceAll("_", " ")}</span><div><b>{stage.id.replaceAll("_", " ")}</b><small>{stage.message}</small></div></div>)}{job.outcome && <div className="dashboard-v2-job-outcome"><b>Evidence outcome: {job.outcome.code.replaceAll("_", " ")}</b><p>{job.outcome.explanation}</p><small>{job.outcome.reviewableCandidateCount} candidate(s) for review · {job.outcome.insufficientCandidateCount} insufficient · {job.outcome.excludedCandidateCount} excluded · {job.outcome.sourceFailureCount} provider failure(s)</small></div>}{job.error && <Notice tone="error">{job.error}</Notice>}{job.status === "completed" && job.discoveryRunId && <Link className="primary-button" to={`/dashboard/runs/${encodeURIComponent(job.discoveryRunId)}`}>Open actual discovery results →</Link>}</> : <p>The job panel will show actual API stage updates after a supported search is started.</p>}</Panel></div>
  </div>;
}

function LatestResults() {
  const latest = useRemote<DiscoveryRun | null>("/discovery-runs/latest", null);
  return <div className="dashboard-v2-page">{latest.loading && <p role="status">Loading the latest stored discovery…</p>}{latest.error && <Notice tone="error">No latest discovery results could be loaded: {latest.error}</Notice>}{latest.data && <Results runId={latest.data.runId} />}{!latest.loading && !latest.error && !latest.data && <Panel><h2>No stored discovery results</h2><p className="dashboard-v2-copy">Run a supported bounded search to create a result record.</p><Link className="primary-button" to="/dashboard/discover">Set up discovery</Link></Panel>}</div>;
}

function RunsV2() {
  const discovery = useRemote<{ runs: HistoryRun[] }>("/discovery-runs", { runs: [] });
  const uniqueRuns = [...new Map(discovery.data.runs.map((run) => [run.runId, run])).values()].sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
  const scopeText = (run: HistoryRun) => {
    const bounds = run.searchScope?.bounds;
    return bounds ? `${bounds.minLatitude}–${bounds.maxLatitude}° latitude · ${bounds.minLongitude}–${bounds.maxLongitude}° longitude` : "Search bounds were not recorded in this run summary.";
  };
  return <div className="dashboard-v2-page"><Header eyebrow="RESEARCH HISTORY · STORED DISCOVERIES" title="Research history." description="Stored discovery records for this deployment, shown with their recorded target, study area, search bounds, status, and result count." action={<Link className="primary-button" to="/dashboard/discover">New discovery ↗</Link>} />{discovery.error && <Notice tone="error">Research history could not be loaded: {discovery.error}</Notice>}<Panel>{discovery.loading ? <p role="status">Loading stored discovery records…</p> : uniqueRuns.length ? <div className="dashboard-v2-history-list">{uniqueRuns.map((run) => <article key={run.runId}><div className="dashboard-v2-history-top"><div><span className="eyebrow">{run.targetBody ?? "Target not recorded"} · {run.missionName ?? run.missionId ?? "Mission profile not recorded"}</span><h2>{run.studyArea ?? "Study area not recorded"}</h2></div><span className="dashboard-v2-run-status">Execution status: {run.status ?? "not recorded"}</span></div>{run.outcome && <p><b>Evidence outcome: {run.outcome.code.replaceAll("_", " ")}.</b> {run.outcome.explanation}</p>}<div className="dashboard-v2-history-meta"><span><b>Earth search scope</b>{scopeText(run)}</span><span><b>Created</b>{run.createdAt ? new Date(run.createdAt).toLocaleString() : "Not recorded"}</span><span><b>Candidates for review</b>{run.earthCandidateCount ?? "Not recorded"}</span><span><b>Evaluated cells / exclusions</b>{run.evaluatedCellCount == null ? "Not recorded" : `${run.evaluatedCellCount} / ${run.excludedCandidateCount ?? 0}`}</span></div><div className="dashboard-v2-history-actions"><Link className="text-link" to={`/dashboard/results/${encodeURIComponent(run.runId)}`}>Open original results →</Link>{run.comparisonRunId && <Link className="text-link" to={`/dashboard/compare?run=${encodeURIComponent(run.comparisonRunId)}&candidateRun=${encodeURIComponent(run.runId)}`}>Supporting Earth-reference comparison →</Link>}</div><p className="dashboard-v2-fineprint">A completed execution or valid archive does not certify analog suitability. Candidate evidence and limitations remain attached to the original result.</p></article>)}</div> : <div className="dashboard-v2-empty">No discovery runs are stored yet.</div>}<p className="dashboard-v2-fineprint">Runs are shown as deployment-level stored records. No user-account ownership or private per-user run model is implemented here.</p></Panel></div>;
}

function DashboardNotFound() {
  return <div className="dashboard-v2-page"><div className="not-found-page dashboard-v2-not-found"><div className="not-found-mark" aria-hidden="true">404</div><div className="eyebrow">DASHBOARD · PAGE NOT FOUND</div><h1>404 — Page Not Found</h1><p>This Dashboard page does not exist.</p><Link className="primary-button" to="/dashboard">Return to Dashboard</Link></div></div>;
}

function DataSourcesV2() {
  const summary = useRemote<ApiSummary | null>("/summary", null);
  const references = useRemote<{ records: ReferenceSite[] }>("/references", { records: [] });
  const mars = useRemote<any>("/mars-evidence/rems", null);
  const moon = useRemote<any>("/moon/summary", null);
  const moonDatasets = useRemote<{ items: any[] }>("/moon/datasets?offset=0&limit=13", { items: [] });
  const candidates = summary.data?.latestDiscovery?.candidates ?? [];
  const countState = (key: string, state: string) => candidates.filter((candidate: any) => candidate.recordType === "candidate_region" && candidate.sources?.[key]?.status === state).length;
  return <div className="dashboard-v2-page"><Header eyebrow="DATA & SOURCES · LIVE INVENTORY" title="Inspect the evidence sources." description="Source status is read from the current stored records. A configured integration, acquired product, and validated dataset are different states." />
    <Panel><span className="eyebrow">EARTH · REFERENCE ARCHIVE AND DISCOVERY SOURCES</span><h2>Earth evidence</h2>{references.loading || summary.loading ? <p role="status">Loading stored Earth source records…</p> : references.error || summary.error ? <Notice tone="error">Earth evidence inventory could not be loaded: {references.error || summary.error}</Notice> : <p>{references.data.records.length} curated Earth reference records. Latest stored bounded run: {countState("climate", "success")} climate retrieval(s) succeeded, {countState("climate", "failed")} failed; {countState("terrain", "success")} elevation retrieval(s) succeeded, {countState("terrain", "failed")} failed; {countState("geology", "success")} geology lookups succeeded, {countState("geology", "failed")} failed. These counts describe candidate cells in the latest run only.</p>}<ul className="dashboard-v2-method-list"><li><b>NASA POWER Daily Point</b><span>Daily gridded climate estimates, not ground-station observations. Valid candidate histories retain requested coordinates, units, observation periods, and missing values.</span></li><li><b>Copernicus DEM GLO-30</b><span>Configured point retrieval of a digital surface model sample. A single elevation is not slope, roughness, relief, or suitability. A failed request stays failed.</span></li><li><b>GLiM v1.1</b><span>Generalized mapped lithology. Multiple intersecting polygons remain ambiguous; this is not mineral detection or site-scale field verification.</span></li></ul></Panel>
    <Panel><span className="eyebrow">MARS · IN-SITU OBSERVATIONS</span><h2>Curiosity REMS</h2>{mars.loading ? <p role="status">Loading the stored Mars evidence record…</p> : mars.error ? <Notice tone="error">REMS evidence could not be loaded: {mars.error}</Notice> : <ul className="dashboard-v2-method-list"><li><b>{mars.data?.dataset?.datasetId ?? "Dataset identifier not recorded"}</b><span>{mars.data?.dataset?.provider ?? "Provider not recorded"} · {mars.data?.measurement?.type ?? "Measurement definition not recorded"} · {mars.data?.measurement?.unit ?? "unit not recorded"}. {mars.data?.qualityControl?.validSampleCount?.toLocaleString?.() ?? "—"} accepted, {mars.data?.qualityControl?.rejectedSampleCount?.toLocaleString?.() ?? "—"} rejected samples across {mars.data?.coverage?.selectedSolCount ?? "—"} selected sols.</span></li><li><b>Interpretation boundary</b><span>REMS is rover air-temperature evidence at Gale Crater. It has different measurement height, sampling cadence, and spatial support than NASA POWER Earth estimates; the candidate-to-target view is descriptive and ambiguous.</span></li></ul>}</Panel>
    <Panel><span className="eyebrow">MOON · PRODUCT REGISTRY</span><h2>Registered is not the same as acquired</h2>{moon.loading || moonDatasets.loading ? <p role="status">Loading the Moon registry…</p> : moon.error || moonDatasets.error ? <Notice tone="error">Moon registry could not be loaded.</Notice> : <><p>{moon.data?.counts?.registered ?? moonDatasets.data.items.length} registered families · {moon.data?.counts?.acquired ?? 0} acquired · {moon.data?.counts?.processed ?? 0} processed · {moon.data?.counts?.validated ?? 0} validated · {moon.data?.counts?.renderable ?? 0} renderable scientific layers. LOLA LDEM_4 display derivatives are research previews.</p><div className="dashboard-v2-method-grid">{moonDatasets.data.items.map((item) => <article className="dashboard-v2-panel" key={item.datasetId}><span className="eyebrow">{item.category ?? item.family ?? "Moon product"}</span><h3>{item.name ?? item.datasetId}</h3><p>{item.provider ?? "Provider not recorded"} · {item.selectedProduct?.productId ?? item.productId ?? "product not selected"}</p><small>Acquisition: {item.lifecycle?.acquisition ?? "not recorded"} · processing: {item.lifecycle?.processing ?? "not recorded"} · validation: {item.lifecycle?.validation ?? "not recorded"} · delivery: {item.lifecycle?.delivery ?? "not recorded"}</small><p>{item.limitations?.[0] ?? "Consult source-specific coverage and measurement metadata before use."}</p></article>)}</div></>}</Panel>
    <Panel><p className="dashboard-v2-copy">These APIs expose application evidence and product metadata, not raw provider credentials or private local paths. For how evidence is screened and compared, read the <Link to="/dashboard/methodology">methodology</Link>.</p></Panel>
  </div>;
}

function MethodologyV2() {
  const references = useRemote<{ records: ReferenceSite[] }>("/references", { records: [] });
  const moon = useRemote<any>("/moon/summary", null);
  const moonDatasets = useRemote<{ items: any[] }>("/moon/datasets?offset=0&limit=13", { items: [] });
  const mars = useRemote<any>("/mars-evidence/rems", null);
  const counts = moon.data?.counts;
  return <div className="dashboard-v2-page"><Header eyebrow="DATA & METHODOLOGY · PROVENANCE" title="Know what each source measures." description="Sources are grouped by target context. Registered metadata, acquired measurements, derived products, and validated map layers are different states." />
    <div className="dashboard-v2-method-grid">
      <Panel><span className="eyebrow">EARTH DATA SOURCES</span><h2>Candidate and reference evidence</h2><ul className="dashboard-v2-method-list"><li><b>NASA POWER</b><span>Daily gridded climate estimates. They are model-derived Earth data, not field-station observations. Values, periods, units, and valid counts are attached to stored candidate evidence.</span></li><li><b>Copernicus DEM GLO-30</b><span>Point samples from a digital surface model. A sample is not slope, roughness, mobility, or a suitability assessment.</span></li><li><b>GLiM v1.1</b><span>Generalized mapped lithology. Polygon classes are not local field verification or mineral assays.</span></li><li><b>Curated references</b><span>{references.loading ? "Loading current archive…" : references.error ? "Reference archive could not be read." : `${references.data.records.length} stored Earth reference records; curation controls point-comparison eligibility.`}</span></li></ul></Panel>
      <Panel><span className="eyebrow">MARS DATA SOURCES</span><h2>Mission context and observations</h2><ul className="dashboard-v2-method-list"><li><b>Curiosity REMS</b><span>{mars.loading ? "Loading the stored observation summary…" : mars.error ? "REMS summary is currently unavailable." : `${mars.data?.qualityControl?.validSampleCount?.toLocaleString?.() ?? "Valid sample count not reported"} accepted and ${mars.data?.qualityControl?.rejectedSampleCount?.toLocaleString?.() ?? "rejected count not reported"} rejected samples across ${mars.data?.coverage?.selectedSolCount ?? "unreported"} selected sols (${mars.data?.measurement?.unit ?? "unit not reported"}). These are in-situ rover air-temperature measurements; cadence and measurement height differ from Earth gridded climate.`}</span></li><li><b>Mars mission profiles</b><span>Versioned required/optional factors organize evidence collection. A profile requirement is not a weighting, score, or mission-readiness threshold.</span></li></ul></Panel>
      <Panel><span className="eyebrow">MOON DATA SOURCES</span><h2>Registered families and current status</h2>{moon.loading || moonDatasets.loading ? <p role="status">Loading Moon registry…</p> : moon.error || moonDatasets.error ? <Notice tone="error">Moon registry details could not be loaded.</Notice> : <><p className="dashboard-v2-copy">{counts?.registered ?? moonDatasets.data.items.length} families are registered. Current lifecycle: {counts?.acquired ?? 0} acquired, {counts?.processed ?? 0} processed, {counts?.validated ?? 0} validated, {counts?.renderable ?? 0} renderable layers. LDEM_4 images are research display previews only.</p><ul className="dashboard-v2-method-list">{moonDatasets.data.items.map((item) => { const lifecycle = item.lifecycle ?? {}; const acquired = lifecycle.acquisition === "completed"; const processed = lifecycle.processing === "completed"; const validated = lifecycle.validation === "completed"; return <li key={item.datasetId}><b>{item.name ?? item.datasetId}</b><span>{item.provider ?? "Provider unrecorded"} · {acquired ? "acquired" : "not acquired"} · {processed ? "processed" : "not processed"} · {validated ? "validated" : "not validated"}. {item.limitations?.[0] ?? "Consult product-specific metadata before interpretation."}</span></li>; })}</ul></>}</Panel>
      <Panel><span className="eyebrow">PROCESSING AND VALIDATION</span><h2>How evidence is handled</h2><ol className="dashboard-v2-method-list ordered"><li><b>Keep source records and derived evidence traceable.</b><span>Acquisition and normalization preserve provenance, periods, units, and missing-value states where available.</span></li><li><b>Screen configured cells with available evidence.</b><span>The currently supported discovery configuration is a bounded Atacama demonstration. It does not scan globally or establish a new analog.</span></li><li><b>Compare compatible Earth evidence factor by factor.</b><span>The existing M08 archive compares candidates with eligible Earth reference records. It is not a candidate-versus-Mars/Moon target comparison.</span></li><li><b>Interpret status as coverage, not confidence.</b><span>Missing or failed evidence is not zero, evidence of absence, or proof that a requirement is met.</span></li></ol></Panel>
    </div>
    <Panel className="dashboard-v2-method-limits"><span className="eyebrow">KNOWN LIMITATIONS</span><p className="dashboard-v2-copy">No overall similarity score, ranking, confirmed analog, or mission-suitability verdict is produced. REMS air temperature and NASA POWER gridded Earth estimates are not same-instrument measurements. Diviner products describe lunar surface/brightness temperatures, not lunar air temperature. Spectral reflectance is not a direct mineral assay; hydrogen and radar indicators do not confirm water ice. LOLA LDEM_4 research previews are not independently validated, georeferenced delivery layers.</p></Panel>
  </div>;
}

function Results({ runId }: { runId: string }) {
  const run = useRemote<DiscoveryRun | null>(`/discovery-runs/${encodeURIComponent(runId)}`, null);
  const candidates = run.data?.candidates ?? [];
  const cells = candidates.filter((item) => item.recordType === "candidate_region");
  const reviewable = cells.filter((item) => item.status === "evidence_supported_for_review");
  const insufficient = cells.filter((item) => item.status === "insufficient_evidence");
  const excluded = cells.filter((item) => item.status === "rejected_reference_overlap");
  return <div className="dashboard-v2-page"><Link className="text-link" to="/dashboard/runs">← Results and runs</Link>{run.loading && <p role="status">Loading stored discovery results…</p>}{run.error && <Notice tone="error">This discovery run could not be loaded: {run.error}</Notice>}{run.data && <><Header eyebrow="STORED EARTH DISCOVERY · BOUNDED REGION" title={run.data.studyArea?.label ?? "Discovery results"} description={`${run.data.createdAt} · ${run.data.missionName ?? run.data.missionId ?? "Mission profile not recorded"} · ${runId}`} /><Notice>{reviewable.length ? `${reviewable.length} location(s) have the selected profile's required evidence available for review.` : insufficient.length ? "The run completed, but no eligible candidate has all selected required evidence." : "The run produced no eligible candidate after reference-overlap exclusions."} This does not rank candidates or establish analog suitability. {excluded.length ? `${excluded.length} generated cell(s) were excluded by the reference-overlap rule.` : ""}</Notice><div className="dashboard-v2-results-grid"><Panel><div className="dashboard-v2-panel-head"><div><span className="eyebrow">EARTH CANDIDATES · EVIDENCE GATE PASSED</span><h2>{reviewable.length} candidate(s) for review</h2></div></div>{reviewable.length ? <CandidateMap candidates={reviewable} /> : <div className="dashboard-v2-empty">No map markers are shown because no eligible cell passed the required-evidence gate.</div>}</Panel><Panel><span className="eyebrow">ACTUAL RUN OUTPUT</span><h2>Evidence-supported candidates</h2><CandidateRows candidates={reviewable} runId={runId} emptyMessage={cells.length ? "No candidate cell passed the profile's evidence gate; excluded and insufficient cells are not presented as discoveries." : "No candidate locations are stored in this run."} />{insufficient.length > 0 && <details className="dashboard-v2-incomplete-cells"><summary>{insufficient.length} evaluated cell(s) with insufficient evidence</summary><CandidateRows candidates={insufficient} runId={runId} supportedOnly={false} /></details>}{excluded.length > 0 && <details className="dashboard-v2-incomplete-cells"><summary>{excluded.length} generated cell(s) excluded by reference overlap</summary><CandidateRows candidates={excluded} runId={runId} supportedOnly={false} /></details>}<p className="dashboard-v2-fineprint">{cells.length} generated cell records · {excluded.length} overlap exclusion(s). Excluded cells are not candidate results.</p></Panel></div>{run.data.comparisonRunId && <p className="dashboard-v2-copy">Supporting Earth-reference comparison archive: <Link to={`/dashboard/compare?run=${encodeURIComponent(run.data.comparisonRunId)}&candidateRun=${encodeURIComponent(runId)}`}>{run.data.comparisonRunId} →</Link></p>}</>}</div>;
}

function CandidateV2({ candidateId }: { candidateId: string }) {
  const query = new URLSearchParams(useLocation().search);
  const run = query.get("run");
  const path = `/candidates/${encodeURIComponent(candidateId)}/evidence${run ? `?run=${encodeURIComponent(run)}` : ""}`;
  const result = useRemote<CandidateEvidence | null>(path, null);
  const candidate = result.data?.candidate;
  const summaries = ["climate", "terrain", "geology"].map((key) => [key, result.data?.sources?.[key]] as const);
  const comparePath = `/dashboard/compare?candidate=${encodeURIComponent(candidateId)}${run ? `&discovery=${encodeURIComponent(run)}` : ""}`;
  return <div className="dashboard-v2-page"><Link className="text-link" to={run ? `/dashboard/history/${encodeURIComponent(run)}` : "/dashboard/explore"}>← Back to Earth candidates</Link>{result.loading && <p role="status">Loading candidate evidence…</p>}{result.error && <Notice tone="error">Candidate evidence could not be loaded: {result.error}</Notice>}{candidate && <><Header eyebrow="EARTH CANDIDATE · SOURCE EVIDENCE" title={candidate.id} description={`${candidate.latitude.toFixed(4)}°, ${candidate.longitude.toFixed(4)}° · approximate grid-cell center`} action={<Link className="secondary-button" to={comparePath}>Compare with target →</Link>} /><Notice>This is an evaluated Earth grid cell. Evidence availability does not make it a confirmed Mars analog or a mission-suitability result.</Notice><Panel><div className="dashboard-v2-evidence-grid">{summaries.map(([key, source]) => <article key={key}><span className="eyebrow">{key === "climate" ? "NASA POWER · GRIDDED CLIMATE" : key === "terrain" ? "COPERNICUS GLO-30 · DSM" : "GLiM · MAPPED GEOLOGY"}</span><b>{source?.status?.replaceAll("_", " ") ?? "No stored evidence"}</b><span>{source?.provider ?? "Provider not recorded"}</span>{source?.actualObservationPeriod && <small>Observation period: {source.actualObservationPeriod.start} to {source.actualObservationPeriod.end}</small>}{source?.requestedCoordinate && <small>Requested point: {source.requestedCoordinate.latitude}°, {source.requestedCoordinate.longitude}° · approximate candidate cell</small>}{source?.elevation && <span>Elevation sample: {source.elevation.value ?? "not recorded"} {source.elevation.unit ?? "m"}</span>}{source?.summaries && Object.entries(source.summaries).map(([id, raw]: [string, any]) => <small key={id}>{id}: {raw?.mean == null ? "not recorded" : `mean ${raw.mean} ${raw.unit ?? ""}; range ${raw.minimum ?? "—"} to ${raw.maximum ?? "—"}; ${raw.validObservationCount ?? "?"} valid of ${raw.requestedDayCount ?? "?"} days`}</small>)}{source?.error && <small>{source.error}</small>}</article>)}</div><div className="dashboard-v2-evidence-list"><h2>Factor evidence</h2>{candidate.evidence?.length ? candidate.evidence.map((item: any) => <article key={item.factorId}><b>{item.factorId.replaceAll("_", " ")}</b><span>{item.sourceId ?? "Source unavailable"} · {item.unit ?? "unit not recorded"}</span><p>{item.note ?? "No explanation was stored for this factor."}</p><span className="state">{item.status?.replaceAll("_", " ")}</span></article>) : <p>No factor evidence recorded in this candidate response.</p>}</div><p className="dashboard-v2-copy">Mission profile: {candidate.missionId ?? "Not recorded"}. Candidate data is linked to the stored run and must be interpreted with its source period, resolution, and limitations.</p><Link className="secondary-button" to={comparePath}>Open target comparison →</Link></Panel></>}</div>;
}

function TemperatureStats({ stats, unit }: { stats: MarsTemperatureContext["candidate"]["statistics"]; unit: string }) {
  return <dl className="dashboard-v2-temperature-stats"><div><dt>Mean</dt><dd>{stats.mean.toFixed(2)} {unit}</dd></div><div><dt>Minimum</dt><dd>{stats.min.toFixed(2)} {unit}</dd></div><div><dt>25th percentile</dt><dd>{stats.q25.toFixed(2)} {unit}</dd></div><div><dt>Median</dt><dd>{stats.median.toFixed(2)} {unit}</dd></div><div><dt>75th percentile</dt><dd>{stats.q75.toFixed(2)} {unit}</dd></div><div><dt>Maximum</dt><dd>{stats.max.toFixed(2)} {unit}</dd></div></dl>;
}

function CompareV2() {
  const location = useLocation();
  const navigate = useNavigate();
  const params = new URLSearchParams(location.search);
  const summary = useRemote<ApiSummary | null>("/summary", null);
  const comparisonRuns = useRemote<{ runs: RunSummary[] }>("/comparison-runs", { runs: [] });
  const references = useRemote<{ records: ReferenceSite[] }>("/references", { records: [] });
  const discoveryId = params.get("discovery") ?? params.get("candidateRun");
  const run = useRemote<DiscoveryRun | null>(discoveryId ? `/discovery-runs/${encodeURIComponent(discoveryId)}` : "/discovery-runs/latest", null);
  const associatedComparisonId = params.get("run") ?? (discoveryId ? dashboardComparisonForDiscovery(comparisonRuns.data.runs, discoveryId) : null);
  const comparisonPath = associatedComparisonId ? `/comparison-runs/${encodeURIComponent(associatedComparisonId)}?offset=0&limit=12` : discoveryId ? null : "/comparison-runs/latest?offset=0&limit=12";
  const selectedCandidate = params.get("candidate") ?? "";
  const selectedReference = params.get("reference") ?? "";
  const selectedEarthRecord = selectedReference || selectedCandidate;
  const earthRecordType = selectedReference ? "reference" : "candidate";
  const [body, setBody] = useState<"mars" | "moon">("mars");
  const [comparison, setComparison] = useState<Comparison | null>(null);
  const [comparisonError, setComparisonError] = useState("");
  useEffect(() => { let active = true; const load = async () => { if (!comparisonPath) { setComparison(null); setComparisonError(""); return; } try { const payload = await api<Comparison>(comparisonPath); if (active) { setComparison(payload); setComparisonError(""); } } catch (error) { if (active) { setComparison(null); setComparisonError((error as Error).message); } } }; void load(); return () => { active = false; }; }, [comparisonPath]);
  const targetRunId = run.data?.runId ?? discoveryId;
  const candidateRows = (run.data?.candidates ?? []).filter((item) => item.recordType === "candidate_region" && item.status === "evidence_supported_for_review");
  const pairCandidateA = params.get("candidateA") ?? candidateRows[0]?.id ?? "";
  const pairCandidateB = params.get("candidateB") ?? candidateRows.find((item) => item.id !== pairCandidateA)?.id ?? "";
  const candidatePairQuery = targetRunId && pairCandidateA && pairCandidateB ? new URLSearchParams({ candidateA: pairCandidateA, runA: targetRunId, candidateB: pairCandidateB, runB: targetRunId }) : null;
  const candidatePair = useRemote<any>(candidatePairQuery ? `/candidate-comparisons/climate?${candidatePairQuery}` : null, null);
  const matrixRows = comparison?.comparisons.filter((pair) => !selectedCandidate || pair.candidateId === selectedCandidate) ?? [];
  const readiness = dashboardTargetAvailability(body);
  const targetPath = body !== "mars" ? null : selectedCandidate && targetRunId ? `/target-comparisons/mars-temperature?candidateId=${encodeURIComponent(selectedCandidate)}&runId=${encodeURIComponent(targetRunId)}` : selectedReference ? `/target-comparisons/mars-temperature?referenceId=${encodeURIComponent(selectedReference)}` : null;
  const marsTemperature = useRemote<MarsTemperatureContext | null>(targetPath, null);
  return <div className="dashboard-v2-page"><Header eyebrow="COMPARE · SCIENTIFIC CLAIM BOUNDARIES" title="Candidate versus planetary target." description="The intended comparison is an Earth candidate against a Mars or Moon environment—not an Earth site against another Earth site." />
    <Panel><div className="dashboard-v2-form-grid"><label>Earth record type<select value={earthRecordType} onChange={(event) => { const next = new URLSearchParams(location.search); next.delete("candidate"); next.delete("reference"); next.delete("discovery"); if (event.target.value === "candidate" && candidateRows[0]) { next.set("candidate", candidateRows[0].id); if (targetRunId) next.set("discovery", targetRunId); } else if (event.target.value === "reference") { const eligible = references.data.records.find((item) => item.curation?.pointComparisonEligible); if (eligible) next.set("reference", eligible.id); } navigate(`${location.pathname}${next.size ? `?${next}` : ""}`); }}><option value="candidate">Discovered Earth candidate</option><option value="reference">Curated Earth reference</option></select></label>{earthRecordType === "candidate" ? <label>Earth candidate<select value={selectedCandidate} onChange={(event) => { const next = new URLSearchParams(location.search); if (event.target.value) next.set("candidate", event.target.value); else next.delete("candidate"); navigate(`${location.pathname}${next.size ? `?${next}` : ""}`); }}><option value="">Select a candidate with required evidence</option>{candidateRows.map((item) => <option key={item.id} value={item.id}>{item.id} · {item.latitude.toFixed(3)}°, {item.longitude.toFixed(3)}°</option>)}</select></label> : <label>Earth reference<select value={selectedReference} onChange={(event) => { const next = new URLSearchParams(location.search); if (event.target.value) next.set("reference", event.target.value); else next.delete("reference"); navigate(`${location.pathname}${next.size ? `?${next}` : ""}`); }}><option value="">Select a curation-eligible reference</option>{references.data.records.filter((item) => item.curation?.pointComparisonEligible).map((item) => <option key={item.id} value={item.id}>{item.regionName ?? item.id} · {item.id}</option>)}</select></label>}<label>Target body<select value={body} onChange={(event) => setBody(event.target.value as "mars" | "moon")}><option value="mars">Mars · Gale Crater REMS context</option><option value="moon">Moon</option></select></label></div>
      {body === "moon" ? <Notice>{readiness.message} No lunar candidate-to-target comparison is generated.</Notice> : !selectedEarthRecord ? <Notice>Select an Earth candidate or a curation-eligible Earth reference to load stored NASA POWER observations alongside the Curiosity REMS evidence.</Notice> : marsTemperature.loading ? <p role="status">Loading NASA POWER and REMS evidence…</p> : marsTemperature.error ? <Notice tone="error">Temperature evidence context could not be loaded: {marsTemperature.error}</Notice> : marsTemperature.data && <><Notice>AMBIGUOUS descriptive context: the values share temperature units, but measurement height, instrument, spatial support, sampling cadence, and observation period are not harmonized. No direct difference or similarity score is calculated.</Notice><div className="dashboard-v2-target-temperature"><article><span className="eyebrow">{earthRecordType === "reference" ? "EARTH REFERENCE · NASA POWER" : "EARTH CANDIDATE · NASA POWER"}</span><h2>{earthRecordType === "reference" ? references.data.records.find((item) => item.id === selectedReference)?.regionName ?? selectedReference : marsTemperature.data.candidate.source}</h2><p>{marsTemperature.data.candidate.measurementType}</p><p>{marsTemperature.data.candidate.period?.start ?? "Period unrecorded"} to {marsTemperature.data.candidate.period?.end ?? "period unrecorded"} · {marsTemperature.data.candidate.statistics.count.toLocaleString()} valid daily means</p><TemperatureStats stats={marsTemperature.data.candidate.statistics} unit={marsTemperature.data.unit} /></article><article><span className="eyebrow">MARS TARGET CONTEXT · CURIOSITY REMS</span><h2>{marsTemperature.data.target.source}</h2><p>{marsTemperature.data.target.measurementType}</p><p>{marsTemperature.data.target.solCount} selected sols ({marsTemperature.data.target.solRange.first}–{marsTemperature.data.target.solRange.last}); {marsTemperature.data.target.acceptedRawSampleCount.toLocaleString()} accepted and {marsTemperature.data.target.rejectedRawSampleCount.toLocaleString()} rejected raw samples. Distribution is across per-sol sample means.</p><TemperatureStats stats={marsTemperature.data.target.statisticsAcrossSelectedSolMeans} unit={marsTemperature.data.unit} /></article></div><p className="dashboard-v2-fineprint">{marsTemperature.data.method}</p><ul className="dashboard-v2-claim-limitations">{marsTemperature.data.limitations.map((item) => <li key={item}>{item}</li>)}</ul></>}
      <div className="dashboard-v2-target-links"><Link className="secondary-button" to={body === "moon" ? "/moon/evidence" : "/mars-evidence"}>Review {body === "moon" ? "Moon evidence gaps" : "Mars observational evidence"} →</Link><Link className="text-link" to="/methodology">Read methods and limitations →</Link></div>
    </Panel>
      <Panel><div className="dashboard-v2-panel-head"><div><span className="eyebrow">SAME-SOURCE EARTH COMPARISON</span><h2>Candidate × candidate climate</h2></div></div><p className="dashboard-v2-copy">Compares valid NASA POWER values on matching dates only. Differences are descriptive for this shared gridded product; they are not analog scores.</p><div className="dashboard-v2-form-grid"><label>Candidate A<select value={pairCandidateA} onChange={(event)=>{const next=new URLSearchParams(location.search);if(event.target.value)next.set("candidateA",event.target.value);else next.delete("candidateA");if(pairCandidateB)next.set("candidateB",pairCandidateB);if(targetRunId)next.set("discovery",targetRunId);navigate(`${location.pathname}?${next}`);}}><option value="">Select a reviewable candidate</option>{candidateRows.map((item)=><option key={item.id} value={item.id} disabled={item.id===pairCandidateB}>{item.id}</option>)}</select></label><label>Candidate B<select value={pairCandidateB} onChange={(event)=>{const next=new URLSearchParams(location.search);if(pairCandidateA)next.set("candidateA",pairCandidateA);if(event.target.value)next.set("candidateB",event.target.value);else next.delete("candidateB");if(targetRunId)next.set("discovery",targetRunId);navigate(`${location.pathname}?${next}`);}}><option value="">Select a different candidate</option>{candidateRows.map((item)=><option key={item.id} value={item.id} disabled={item.id===pairCandidateA}>{item.id}</option>)}</select></label></div>{candidateRows.length<2?<Notice>Two reviewable Earth candidates with stored climate histories are needed for this comparison.</Notice>:candidatePair.loading?<p role="status">Loading paired-date climate evidence…</p>:candidatePair.error?<Notice tone="error">Candidate climate comparison unavailable: {candidatePair.error}</Notice>:candidatePair.data&&<><Notice>DESCRIPTIVE comparison. Valid same-date NASA POWER records only; gaps are not filled.</Notice><div className="dashboard-v2-history-meta">{[candidatePair.data.records.candidateA,candidatePair.data.records.candidateB].map((record:any,index:number)=><span key={index}><b>Candidate {index===0?"A":"B"} · {record.candidateId}</b>{record.requestedCoordinate?`${record.requestedCoordinate.latitude}°, ${record.requestedCoordinate.longitude}°`:"Coordinate not recorded"}<br/>{record.period?.start??"Period unrecorded"} to {record.period?.end??"unrecorded"} · {record.temporalResolution??"Temporal resolution unrecorded"}<br/>{record.spatialResolution??"Spatial resolution unrecorded"}<br/>Source: {record.source??"not recorded"}</span>)}</div><div className="dashboard-v2-reference-pairs">{candidatePair.data.factors.map((factor:any)=><article key={factor.parameterId}><b>{factor.parameterId}</b><small>{factor.status==="compared"?`${factor.pairedObservationCount.toLocaleString()} paired days · ${factor.period.start} to ${factor.period.end} · ${factor.unit}`:factor.reason}</small>{factor.status==="compared"&&<p>{factor.identicalMatchedValues?"All paired values are identical for this parameter. ":""}Candidate A mean {factor.candidateA.mean.toFixed(2)} {factor.unit}; Candidate B mean {factor.candidateB.mean.toFixed(2)} {factor.unit}; mean B − A {factor.differenceBMinusA.mean.toFixed(2)} {factor.unit}.</p>}</article>)}</div><ul className="dashboard-v2-claim-limitations">{candidatePair.data.limitations.map((item:string)=><li key={item}>{item}</li>)}</ul></>}</Panel>
      <Panel><div className="dashboard-v2-panel-head"><div><span className="eyebrow">SUPPORTING CONTEXT ONLY</span><h2>Earth candidate × Earth reference archive</h2></div><Link className="text-link" to="/comparison">Open archived comparison view →</Link></div><p className="dashboard-v2-copy">This is the existing M08 supporting Earth-reference operation. It is not the primary product outcome and does not identify an Earth/Mars or Earth/Moon analog.</p>{summary.loading || run.loading || (!params.get("run") && discoveryId && comparisonRuns.loading) ? <p role="status">Loading archived evidence records…</p> : comparisonError ? <div className="dashboard-v2-empty">No supporting reference matrix is available: {comparisonError}</div> : discoveryId && comparisonRuns.error && !params.get("run") ? <div className="dashboard-v2-empty">Stored comparisons could not be checked: {comparisonRuns.error}</div> : !comparisonPath ? <div className="dashboard-v2-empty">No stored Earth-reference matrix is linked to this discovery. No candidate-to-target comparison is generated.</div> : matrixRows.length ? <div className="dashboard-v2-reference-pairs">{matrixRows.slice(0, 6).map((pair) => <article key={`${pair.candidateId}-${pair.referenceSiteId}`}><b>{pair.candidateId}</b><span>×</span><b>{pair.referenceSiteId}</b><small>{pair.factors.length} factor records · statuses remain as stored</small><details><summary>Inspect factor states</summary>{pair.factors.map((factor) => <p key={factor.factorId}><b>{factor.factorId.replaceAll("_", " ")}</b> · {factor.status.replaceAll("_", " ")} · {factor.explanation}</p>)}</details></article>)}</div> : <div className="dashboard-v2-empty">No archived Earth-reference factor pairs match this selection.</div>}</Panel>
  </div>;
}
